"""Canonical site stylesheet. wiki_builder.py writes this to
static/<lang>/assets/style.css; edit it here, never the built file."""

SHARED = '/* ================= shared design tokens =================\n   One palette for the portal index and every document page. Medium-style:\n   Georgia headings, generous measure, hairline rules, near-black ink. */\n:root {\n  --ink:#191919; --ink-2:#333333; --muted:#757575; --muted-2:#999999;\n  --rule:#e6e6e6; --rule-2:#f0f0f0; --surface:#ffffff; --chip:#f2f2f2;\n  --bg:#ffffff; --link:#0f6cbd;\n  --serif:Georgia,"Times New Roman",Times,serif;\n  --sans:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;\n  --measure:720px;\n}\n\n*, *::before, *::after { box-sizing:border-box; }\n\nhtml { -webkit-text-size-adjust:100%; }\n\nbody {\n  margin:0; padding:0; max-width:none;\n  background:var(--bg); color:var(--ink);\n  font-family:var(--sans); line-height:1.6;\n  -webkit-font-smoothing:antialiased;\n}\n\nimg, svg, video, table { max-width:100%; }\n\nimg, video { height:auto; }\n\n\n/* ================= portal index (Medium-style) =================\n   Kept ABOVE the document-pages marker so scripts/wiki_builder.py, which\n   rewrites everything after the marker, preserves it. */\nbody.portal {\n  color:var(--ink);\n  background:var(--bg);\n  line-height:1.6;\n  max-width:none; margin:0; padding:0;\n}\n\nbody.portal * { box-sizing:border-box; }\n\nbody.portal a { color:inherit; text-decoration:none; }\n\n.wrap { max-width:1180px; margin:0 auto; padding:0 24px; }\n\n\n.site-header {\n  position:sticky; top:0; z-index:20;\n  background:rgba(255,255,255,0.92);\n  backdrop-filter:saturate(180%) blur(12px);\n  border-bottom:1px solid var(--rule);\n}\n\n.header-inner { display:flex; align-items:center; gap:28px; height:64px; }\n\n.brand { font-family:var(--serif); font-size:1.32rem; font-weight:700; letter-spacing:-0.02em; }\n\na.brand { color:inherit; text-decoration:none; }\n\n.header-nav { display:flex; gap:22px; font-size:0.9rem; }\n\n.header-nav a { color:var(--ink-2); }\n\n.header-nav a:hover { color:var(--ink); }\n\n\n.header-actions { display:flex; align-items:center; gap:10px; margin-left:auto; }\n.theme-toggle {\n  font-size:0.95rem; line-height:1; color:var(--ink-2);\n  border:1px solid var(--rule); border-radius:999px; background:none;\n  width:32px; height:32px; padding:0; cursor:pointer;\n}\n.theme-toggle:hover { border-color:var(--ink-2); color:var(--ink); }\n.lang-menu { position:relative; }\n.lang-menu summary {\n  list-style:none; cursor:pointer; font-size:0.78rem; text-transform:uppercase; letter-spacing:0.08em;\n  color:var(--muted); border:1px solid var(--rule); border-radius:999px; padding:5px 13px;\n}\n.lang-menu summary::-webkit-details-marker { display:none; }\n.lang-menu summary::marker { content:""; }\n.lang-menu summary:hover { border-color:var(--ink-2); color:var(--ink); }\n.lang-menu ul {\n  position:absolute; right:0; top:calc(100% + 8px); margin:0; padding:6px; min-width:150px;\n  list-style:none; background:var(--surface); border:1px solid var(--rule); border-radius:10px;\n  box-shadow:0 8px 24px rgba(0,0,0,0.12); z-index:30;\n}\n.lang-menu li { margin:0; }\n.lang-menu a {\n  display:block; padding:8px 12px; border-radius:6px; font-size:0.88rem;\n  color:var(--ink-2); text-decoration:none; white-space:nowrap;\n}\n.lang-menu a:hover { background:var(--chip); color:var(--ink); }\n.lang-menu a[aria-current="page"] { font-weight:700; color:var(--ink); }\n.lang-menu a.is-fallback { opacity:0.55; }\n\n\n.layout { display:grid; grid-template-columns:288px minmax(0,1fr); gap:56px; align-items:start; }\n\n\n.sidebar { position:sticky; top:88px; max-height:calc(100vh - 112px); overflow-y:auto; padding:28px 0 40px; }\n\n.sidebar-title {\n  font-size:0.72rem; text-transform:uppercase; letter-spacing:0.1em;\n  color:var(--muted); margin:0 0 12px;\n}\n\n.search {\n  width:100%; padding:9px 12px; margin-bottom:16px;\n  border:1px solid var(--rule); border-radius:6px; background:var(--chip);\n  font-family:var(--sans); font-size:0.88rem; color:var(--ink);\n}\n\n.search:focus { outline:none; background:#fff; border-color:var(--muted-2); }\n\n.nav-tree { font-size:0.86rem; }\n\n.nav-group { border-bottom:1px solid var(--rule-2); padding:9px 0; }\n\n.nav-group > summary {\n  cursor:pointer; font-weight:600; display:flex; align-items:center; gap:8px;\n  list-style:none; padding:3px 0;\n}\n\n.nav-group > summary::-webkit-details-marker { display:none; }\n\n.nav-group > summary::before { content:"▸"; color:var(--muted); font-size:0.7rem; }\n\n.nav-group[open] > summary::before { content:"▾"; }\n\n.nav-group ul { list-style:none; margin:8px 0 4px; padding-left:14px; }\n\n.nav-group ul ul { margin:2px 0 2px 0; padding-left:12px; }\n\n.nav-subname {\n  display:block; color:var(--muted); font-size:0.74rem;\n  text-transform:uppercase; letter-spacing:0.05em; margin:9px 0 3px;\n}\n\n.nav-sub[hidden], .nav-tree li[hidden] { display:none; }\n\n.nav-sub ul { padding-left:12px; }\n\n.nav-subname em { font-style:normal; color:var(--muted-2); }\n\n.nav-tree a { color:var(--ink-2); display:block; padding:3px 0; line-height:1.42; }\n\n.nav-tree a:hover { color:var(--link); }\n\n.content { min-width:0; }\n\n.facet-count {\n  margin-left:auto; color:var(--muted); font-size:0.74rem; font-weight:400;\n  font-variant-numeric:tabular-nums;\n}\n\n\n.hero { padding:40px 0 8px; border-bottom:1px solid var(--rule); }\n\n.intro {\n  font-family:var(--serif); font-size:1.16rem; line-height:1.6;\n  color:var(--ink-2); margin:0 0 28px; max-width:60ch;\n}\n\n.hero-cards { display:grid; grid-template-columns:repeat(auto-fit,minmax(230px,1fr)); gap:14px; margin-bottom:44px; }\n\n.hero-card {\n  border:1px solid var(--rule); border-radius:8px; padding:16px 18px;\n  display:flex; flex-direction:column; gap:6px; transition:border-color .15s ease;\n}\n\n.hero-card:hover { border-color:var(--muted-2); }\n\n.hero-date { font-size:0.72rem; color:var(--muted); font-variant-numeric:tabular-nums; }\n\n.hero-title { font-family:var(--serif); font-size:1.02rem; line-height:1.34; font-weight:600; }\n\n.hero-kind { font-size:0.72rem; color:var(--muted); }\n\n\n.block { padding:48px 0; border-bottom:1px solid var(--rule); }\n\n.block:last-of-type { border-bottom:0; }\n\n.block h2 {\n  font-family:var(--serif); font-size:1.72rem; letter-spacing:-0.02em;\n  margin:0 0 6px; font-weight:700;\n}\n\n.block-sub { color:var(--muted); font-size:0.92rem; margin:0 0 22px; }\n\n.controls {\n  display:flex; flex-wrap:wrap; gap:12px; justify-content:space-between;\n  align-items:center; margin-bottom:16px;\n}\n\n.chips { display:flex; flex-wrap:wrap; gap:7px; }\n\n.chip {\n  border:1px solid var(--rule); background:#fff; color:var(--ink-2);\n  border-radius:999px; padding:5px 13px; font-size:0.82rem; cursor:pointer;\n  font-family:var(--sans); transition:all .13s ease;\n}\n\n.chip:hover { border-color:var(--muted-2); }\n\n.chip.is-active { background:var(--ink); border-color:var(--ink); color:#fff; }\n\n.selects { display:flex; gap:8px; }\n\n.selects select {\n  font-family:var(--sans); font-size:0.82rem; color:var(--ink-2);\n  border:1px solid var(--rule); border-radius:6px; padding:6px 10px; background:#fff;\n  max-width:230px;\n}\n\n.result-count { color:var(--muted); font-size:0.82rem; margin:0 0 10px; min-height:1.2em; }\n\n\n.doc-table { width:100%; border-collapse:collapse; }\n\n.doc-table th {\n  text-align:left; font-size:0.72rem; text-transform:uppercase;\n  letter-spacing:0.07em; color:var(--muted); font-weight:600;\n  padding:0 12px 9px 0; border-bottom:1px solid var(--ink);\n}\n\n.doc-table td { padding:13px 12px 13px 0; border-bottom:1px solid var(--rule-2); vertical-align:top; font-size:0.92rem; }\n\n.doc-table tbody tr:hover { background:#fcfcfc; }\n\n.t-title { font-family:var(--serif); font-size:1.02rem; line-height:1.36; }\n\n.t-title a:hover { color:var(--link); }\n\n.t-type { width:1%; white-space:nowrap; }\n\n.t-cat, .t-src, .t-date { color:var(--muted); font-size:0.84rem; white-space:nowrap; }\n\n.t-date { font-variant-numeric:tabular-nums; }\n\n.sort-btn {\n  font:inherit; text-transform:inherit; letter-spacing:inherit; color:inherit;\n  background:none; border:0; padding:0; cursor:pointer; font-weight:inherit;\n}\n\n.sort-btn:hover { color:var(--ink); }\n\n.sort-btn .arrow { font-size:0.75em; }\n\n.pager { display:flex; align-items:center; gap:6px; flex-wrap:wrap; margin:14px 0 4px; }\n\n.page-btn {\n  font-family:var(--sans); font-size:0.82rem; color:var(--ink-2);\n  border:1px solid var(--rule); border-radius:6px; background:#fff;\n  min-width:30px; padding:5px 9px; cursor:pointer;\n}\n\n.page-btn:hover { border-color:var(--ink); color:var(--ink); }\n\n.page-btn.is-current { background:var(--ink); border-color:var(--ink); color:#fff; }\n\n.page-btn:disabled { opacity:0.4; cursor:default; }\n\n.page-btn:disabled:hover { border-color:var(--rule); color:var(--ink-2); }\n\n.pager .per-page { margin-left:auto; font-size:0.82rem; color:var(--muted); display:flex; align-items:center; gap:6px; }\n\n.pager .per-page select {\n  font-family:var(--sans); font-size:0.82rem; color:var(--ink-2);\n  border:1px solid var(--rule); border-radius:6px; padding:4px 8px; background:#fff;\n}\n\n.pager .ellipsis { color:var(--muted-2); padding:0 2px; }\n\n.col-toggle { display:none; }\n\n.table-scroll { overflow:visible; }\n\n.tag-chip.is-active { background:var(--ink); color:#fff; border-color:var(--ink); }\n\n.tag-chip.is-active em { color:inherit; opacity:0.7; }\n\n.pill {\n  display:inline-block; font-size:0.7rem; letter-spacing:0.04em;\n  padding:2px 8px; border-radius:999px; background:var(--chip); color:var(--ink-2);\n}\n\n.pill-papers { background:#eef3fb; color:#2a4a7b; }\n\n.pill-articles { background:#f5f0fb; color:#5b3a86; }\n\n.pill-concepts { background:#eaf5ee; color:#2c6340; }\n\n.pill-guides { background:#fdf1e6; color:#8a5324; }\n\n.empty { color:var(--muted); font-size:0.9rem; padding:18px 0; }\n\n\n.facets { display:flex; flex-direction:column; gap:2px; }\n\n.facet { border-bottom:1px solid var(--rule-2); }\n\n.facet > summary {\n  cursor:pointer; list-style:none; padding:13px 0;\n  display:flex; align-items:center; gap:10px; font-weight:600; font-size:0.95rem;\n}\n\n.facet > summary::-webkit-details-marker { display:none; }\n\n.facet > summary::before { content:"▸"; color:var(--muted); font-size:0.7rem; }\n\n.facet[open] > summary::before { content:"▾"; }\n\n.facet-name { font-family:var(--serif); }\n\n.facet .doc-table { margin:0 0 18px; }\n\n.facet .doc-table th { display:none; }\n\n\n.tag-cloud { display:flex; flex-wrap:wrap; gap:8px; }\n\n.tag-chip {\n  border:1px solid var(--rule); border-radius:999px; padding:5px 13px;\n  font-size:0.84rem; color:var(--ink-2); background:#fff;\n}\n\n.tag-chip:hover { border-color:var(--ink-2); color:var(--ink); }\n\n.tag-chip em { font-style:normal; color:var(--muted); font-size:0.76rem; }\n\n\n.site-footer { border-top:1px solid var(--rule); margin-top:24px; padding:28px 0 44px; }\n\n.site-footer p { color:var(--muted); font-size:0.84rem; margin:0; }\n/* ================= responsive =================\n   Three tiers: desktop two-column, tablet stacked, phone single column.\n   Table columns drop in priority order so the title always survives. */\n\n@media (max-width: 1100px) {\n\n  .layout { grid-template-columns:250px minmax(0,1fr); gap:40px; }\n\n  .wrap { padding:0 20px; }\n\n  .t-src { display:none; }\n}\n@media (max-width: 900px) {\n\n  .layout { grid-template-columns:1fr; gap:0; }\n\n  .sidebar {\n    position:static; max-height:none; padding:22px 0 8px;\n    border-bottom:1px solid var(--rule); margin-bottom:8px;\n  }\n\n  .nav-tree { max-height:min(52vh,420px); overflow-y:auto; -webkit-overflow-scrolling:touch; }\n\n  .hero { padding:32px 0 4px; }\n\n  .block { padding:36px 0; }\n\n  .header-nav { display:none; }\n\n  .header-inner { height:56px; }\n\n  .brand { font-size:1.2rem; }\n\n  .header-actions { margin-left:auto; }\n}\n@media (max-width: 720px) {\n\n  .wrap { padding:0 18px; }\n\n  .t-cat, .t-date { display:none; }\n\n  #table-scroll.show-cat .t-cat, #table-scroll.show-date .t-date, #table-scroll.show-src .t-src { display:table-cell; }\n\n  .controls { gap:10px; }\n\n  .selects { width:100%; justify-content:flex-start; flex-wrap:wrap; }\n\n  .selects select { flex:0 1 auto; width:auto; max-width:100%; min-width:0; }\n\n  .col-toggle { display:flex; flex-wrap:wrap; align-items:center; gap:6px; margin:0 0 10px; }\n\n  .col-toggle-label { font-size:0.78rem; color:var(--muted); margin-right:2px; }\n\n  .table-scroll.is-scrollable { overflow-x:auto; -webkit-overflow-scrolling:touch; }\n\n  .table-scroll.is-scrollable .doc-table { min-width:560px; }\n\n  .chips { gap:6px; }\n\n  .chip { padding:4px 11px; font-size:0.78rem; }\n\n  .doc-table td { padding:11px 8px 11px 0; }\n\n  .t-title { font-size:0.98rem; }\n\n  .doc-table tbody tr:hover { background:transparent; }\n}\n@media (max-width: 480px) {\n\n  .wrap { padding:0 15px; }\n\n  .intro { font-size:0.94rem; }\n\n  .block h2 { font-size:1.45rem; }\n\n  .hero-cards { grid-template-columns:1fr; gap:10px; }\n\n  .chips .chip:nth-child(n+4) { display:none; }\n\n  .md-table { display:block; overflow-x:auto; }\n}\n/* touch targets: keep tappable rows and controls finger-sized */\n@media (hover: none) {\n\n  .doc-table td { padding:14px 8px 14px 0; }\n\n  .nav-tree a { padding:6px 0; }\n\n  .chip, .tag-chip { padding:8px 14px; }\n}\n@media (prefers-reduced-motion: reduce) {\n\n  * { animation:none !important; transition:none !important; scroll-behavior:auto !important; }\n}\n@media print {\n\n  .site-header, .sidebar, .controls, .chips, .selects, .site-footer { display:none !important; }\n\n  body, .content { max-width:100%; }\n\n  .doc-body { max-width:100%; }\n\n  a { color:#000; text-decoration:underline; }\n}\n\n/* ---- dark mode ----\n   Single source: dark-flat.css (kept out of the repo). Two scopes are\n   generated from it — explicit toggle first, OS default second.\n   Tokens, then hard-coded light surfaces. No-JS readers stay on the\n   OS branch; the toggle only adds an explicit override. */\n:root { color-scheme: light dark; }\nhtml[data-theme="light"] { color-scheme: light; }\nhtml[data-theme="dark"] { color-scheme: dark; }\nhtml[data-theme="dark"] {\n  --ink:#e9e6e1; --ink-2:#c6c2bb; --muted:#a19d96; --muted-2:#77736c;\n  --rule:#2e2e2e; --rule-2:#262626; --surface:#1e1e1e; --chip:#2b2b2b;\n  --bg:#1e1e1e; --link:#6db3f2;\n}\nhtml[data-theme="dark"] body, html[data-theme="dark"] body.portal {\n  background:var(--bg); color:var(--ink);\n}\nhtml[data-theme="dark"] .site-header {\n  background:rgba(30,30,30,0.92);\n}\nhtml[data-theme="dark"] .chip, html[data-theme="dark"] .tag-chip, html[data-theme="dark"] .page-btn, html[data-theme="dark"] .selects select, html[data-theme="dark"] .pager .per-page select {\n  background:var(--chip);\n}\nhtml[data-theme="dark"] .search:focus {\n  background:var(--chip);\n}\nhtml[data-theme="dark"] .chip.is-active, html[data-theme="dark"] .tag-chip.is-active, html[data-theme="dark"] .page-btn.is-current {\n  background:var(--ink); border-color:var(--ink); color:#1e1e1e;\n}\nhtml[data-theme="dark"] .doc-table tbody tr:hover {\n  background:#242424;\n}\nhtml[data-theme="dark"] .prose pre {\n  background:#262626; border-color:var(--rule); color:var(--ink);\n}\nhtml[data-theme="dark"] .pill-papers {\n  background:#1e2c47; color:#9cc3f5;\n}\nhtml[data-theme="dark"] .pill-articles {\n  background:#2c2342; color:#c9b3f0;\n}\nhtml[data-theme="dark"] .pill-concepts {\n  background:#1d3328; color:#9adbb5;\n}\nhtml[data-theme="dark"] .pill-guides {\n  background:#3a2c1c; color:#e9bf8b;\n}\nhtml[data-theme="dark"] .prose img {\n  filter:brightness(0.94);\n}\nhtml[data-theme="dark"] .lang-menu ul {\n  box-shadow:0 8px 24px rgba(0,0,0,0.45);\n}\n@media (prefers-color-scheme: dark) {\nhtml:not([data-theme]) {\n  --ink:#e9e6e1; --ink-2:#c6c2bb; --muted:#a19d96; --muted-2:#77736c;\n  --rule:#2e2e2e; --rule-2:#262626; --surface:#1e1e1e; --chip:#2b2b2b;\n  --bg:#1e1e1e; --link:#6db3f2;\n}\nhtml:not([data-theme]) body, html:not([data-theme]) body.portal {\n  background:var(--bg); color:var(--ink);\n}\nhtml:not([data-theme]) .site-header {\n  background:rgba(30,30,30,0.92);\n}\nhtml:not([data-theme]) .chip, html:not([data-theme]) .tag-chip, html:not([data-theme]) .page-btn, html:not([data-theme]) .selects select, html:not([data-theme]) .pager .per-page select {\n  background:var(--chip);\n}\nhtml:not([data-theme]) .search:focus {\n  background:var(--chip);\n}\nhtml:not([data-theme]) .chip.is-active, html:not([data-theme]) .tag-chip.is-active, html:not([data-theme]) .page-btn.is-current {\n  background:var(--ink); border-color:var(--ink); color:#1e1e1e;\n}\nhtml:not([data-theme]) .doc-table tbody tr:hover {\n  background:#242424;\n}\nhtml:not([data-theme]) .prose pre {\n  background:#262626; border-color:var(--rule); color:var(--ink);\n}\nhtml:not([data-theme]) .pill-papers {\n  background:#1e2c47; color:#9cc3f5;\n}\nhtml:not([data-theme]) .pill-articles {\n  background:#2c2342; color:#c9b3f0;\n}\nhtml:not([data-theme]) .pill-concepts {\n  background:#1d3328; color:#9adbb5;\n}\nhtml:not([data-theme]) .pill-guides {\n  background:#3a2c1c; color:#e9bf8b;\n}\nhtml:not([data-theme]) .prose img {\n  filter:brightness(0.94);\n}\nhtml:not([data-theme]) .lang-menu ul {\n  box-shadow:0 8px 24px rgba(0,0,0,0.45);\n}\n}\n'

DOC = "/* ---- document pages (scripts/wiki_builder.py) ----\n   Shares the portal's type scale, colour tokens and measure so a doc page\n   reads as the same publication as the index it was reached from. */\n\n.doc-header { border-bottom: 1px solid var(--rule); padding: 40px 0 28px; margin-bottom: 8px; }\n\n.doc-header h1 {\n  font-family: var(--serif); font-size: 2.5rem; line-height: 1.14;\n  letter-spacing: -0.026em; font-weight: 700; margin: 0 0 14px; max-width: 30ch;\n}\n\n.doc-meta {\n  font-size: 0.88rem; color: var(--ink-2); margin: 0 0 7px;\n  display: flex; gap: 10px; align-items: baseline; flex-wrap: wrap;\n}\n\n.doc-meta .label {\n  min-width: 0; text-transform: uppercase; letter-spacing: 0.08em;\n  font-size: 0.68rem; color: var(--muted); font-weight: 600;\n}\n\n.doc-meta a { color: var(--link); text-decoration: underline; text-underline-offset: 2px; }\n\n.doc-meta a:hover { color: var(--ink); }\n\n\n.md-table { width: 100%; border-collapse: collapse; margin: 0 0 1.5em; font-size: 0.9rem; }\n\n.md-table th, .md-table td { border-bottom: 1px solid var(--rule-2); padding: 9px 12px 9px 0; text-align: left; }\n\n.md-table th { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.07em; color: var(--muted); border-bottom-color: var(--ink); }\n\n.md-table td a { color: var(--link); }\n\n\n.toc {\n  border-left: 1px solid var(--rule); padding: 4px 0 4px 22px;\n  margin: 0 0 40px; font-size: 0.9rem;\n}\n\n.toc .toc-title {\n  text-transform: uppercase; letter-spacing: 0.09em; font-size: 0.68rem;\n  color: var(--muted); margin: 0 0 10px; font-weight: 600;\n}\n\n.toc ul { list-style: none; margin: 0; padding: 0; }\n\n.toc li { margin-bottom: 6px; }\n\n.toc a { color: var(--ink-2); text-decoration: none; }\n\n.toc a:hover { color: var(--ink); }\n\n\n.back-link { margin: 48px 0 0; padding-top: 24px; border-top: 1px solid var(--rule); font-size: 0.9rem; }\n\n.back-link a { color: var(--ink-2); text-decoration: none; font-weight: 600; }\n\n.back-link a:hover { color: var(--link); }\n\n\n/* ---- shared: doc pages sit on the same body tokens as the portal ---- */\nbody { background: #fff; color: var(--ink); }\n/* ---- responsive: one column, no horizontal scroll ---- */\n@media (max-width: 720px) {\n\n  .doc-header { padding: 28px 0 22px; }\n\n  .doc-header h1 { font-size: 1.85rem; line-height: 1.2; }\n\n  .doc-meta { font-size: 0.84rem; }\n\n  .toc { padding-left: 14px; margin-bottom: 30px; }\n\n  .md-table { display: block; overflow-x: auto; white-space: nowrap; }\n}\n\n\n/* ---- document pages (scripts/wiki_builder.py) ----\n   Shares the portal's palette, type scale and measure, so an article reads\n   as the same publication as the index that links to it. */\n\n.doc-body { max-width: var(--measure); margin: 0 auto; padding: 0 0 40px; }\n\n\n.doc-header { padding: 40px 0 0; }\n\n.doc-header h1 {\n  font-family: var(--serif); font-size: 2.5rem; line-height: 1.14;\n  letter-spacing: -0.026em; font-weight: 700; margin: 0 0 14px; max-width: 32ch;\n}\n\n.doc-meta .label {\n  text-transform: uppercase; letter-spacing: 0.08em;\n  font-size: 0.68rem; color: var(--muted); font-weight: 600;\n}\n\n\n.prose { font-family: var(--serif); }\n\n.prose h2 {\n  font-size: 1.5rem; letter-spacing: -0.018em; font-weight: 700;\n  margin: 40px 0 12px; line-height: 1.25;\n}\n\n.prose h3 { font-size: 1.2rem; margin: 28px 0 8px; font-weight: 700; }\n\n.prose p { font-size: 1.06rem; line-height: 1.72; margin: 0 0 1.15em; }\n\n.prose ul, .prose ol { margin: 0 0 1.3em 1.35em; }\n\n.prose li { font-size: 1.04rem; line-height: 1.66; margin-bottom: 0.4em; }\n\n.prose a { color: var(--link); text-decoration: underline; text-underline-offset: 2px; }\n\n.prose a:hover { color: var(--ink); }\n\n.prose strong { font-weight: 600; }\n\n.prose code {\n  background: var(--chip); padding: 0.12em 0.34em; border-radius: 4px;\n  font-size: 0.88em; font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n}\n\n.prose pre {\n  background: #f7f7f7; border: 1px solid var(--rule); color: var(--ink);\n  padding: 16px 18px; border-radius: 8px; overflow-x: auto; margin: 0 0 1.5em;\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n}\n\n.prose pre code { background: none; padding: 0; font-size: 0.86rem; line-height: 1.55; }\n\n.prose blockquote {\n  border-left: 2px solid var(--ink); margin: 0 0 1.3em; padding: 2px 0 2px 20px;\n  color: var(--ink-2); font-style: italic;\n}\n\n.prose hr { border: 0; border-top: 1px solid var(--rule); margin: 40px 0; }\n\n.prose img { border-radius: 6px; max-width: 100%; height: auto; }\n\n.prose figure.md-figure { margin: 0 0 1.5em; }\n\n.prose figure.md-figure img { display: block; margin: 0 auto; }\n\n.prose figure.md-figure figcaption { margin-top: 8px; text-align: center; font-family: var(--sans); font-size: 0.85rem; color: var(--muted); }\n\n.prose .math-display { overflow-x: auto; overflow-y: hidden; margin: 0 0 1.3em; padding: 4px 0; }\n\n.prose mjx-container { max-width: 100%; }\n\n.prose figure.md-figure .zoom-in { display: block; cursor: zoom-in; }\n\n.prose .lightbox { display: none; position: fixed; inset: 0; z-index: 100; background: rgba(0,0,0,0.88); padding: 4vmin; text-decoration: none; opacity: 0; transition: opacity .25s ease; }\n\n.prose .lightbox:target { display: flex; align-items: center; justify-content: center; opacity: 1; }\n\n.prose .lightbox.is-open { display: flex; align-items: center; justify-content: center; opacity: 1; overflow: hidden; overscroll-behavior: contain; }\n\n.prose .lightbox img { max-width: 96vw; max-height: 94vh; object-fit: contain; border-radius: 6px; background: #fff; cursor: zoom-out; transition: transform .3s cubic-bezier(.2,.7,.3,1); will-change: transform; }\n\n\n.md-table { width: 100%; border-collapse: collapse; margin: 0 0 1.5em; font-family: var(--sans); font-size: 0.9rem; }\n\n\n.toc { border-left: 1px solid var(--rule); padding: 4px 0 4px 22px; margin: 32px 0 8px; font-size: 0.9rem; }\n\n\n.back-link { margin: 48px 0 0; padding-top: 24px; border-top: 1px solid var(--rule); font-family: var(--sans); font-size: 0.9rem; }\n@media (max-width: 720px) {\n\n  .doc-header { padding: 28px 0 0; }\n\n  .prose p, .prose li { font-size: 1.02rem; }\n\n  .prose h2 { font-size: 1.32rem; margin-top: 32px; }\n\n  .prose h3 { font-size: 1.1rem; margin-top: 24px; }\n\n  .toc { padding-left: 14px; margin-top: 24px; }\n\n  .md-table { display: block; overflow-x: auto; }\n\n  .prose pre { padding: 12px 14px; }\n\n  .wrap { padding: 0 18px; }\n}"
